$f = "KCSA.html"
$c = [System.IO.File]::ReadAllText((Resolve-Path $f))

function Get-Chapter($num) {
    $startTag = "id=`"ch$num`""
    $endTag = if ($num -eq 25) { "id=`"appendix-a`"" } else { "id=`"ch$($num+1)`"" }
    $s = $c.IndexOf($startTag)
    $e = $c.IndexOf($endTag, $s)
    if ($s -lt 0 -or $e -le $s) { return $null }
    return @{ start = $s; end = $e; text = $c.Substring($s, $e - $s) }
}
function Find-InsertPoint($chText, $chStart) {
    $l = $chText.LastIndexOf("</details></div>")
    if ($l -lt 0) { return -1 }
    return $chStart + $l + "</details></div>".Length
}
function Add-ChapterQs($chNum, $qPairs) {
    $ch = Get-Chapter $chNum
    if ($null -eq $ch) { Write-Host "Ch$chNum`: NOT FOUND"; return }
    $ia = Find-InsertPoint $ch.text $ch.start
    if ($ia -lt 0) { Write-Host "Ch$chNum`: NO DRILL"; return }
    $it = ""
    foreach ($p in $qPairs) { $it += "`n" + $p[0] + "`n" + $p[1] }
    $script:c = $c.Substring(0, $ia) + $it + $c.Substring($ia)
    Write-Host "Ch$chNum`: +$($qPairs.Count) Qs"
}

